with valid as (select *, concat_ws(',', browser, country) as browser_country_key, date_format(started_at, 'yyyy-MM-dd') as started_at_label from sessions where country in ('UK', 'US')) select id, customer_id, browser, started_at, country, started_at_label, first_value(browser, true) over (partition by to_date(started_at), country order by started_at, id rows between unbounded preceding and current row) as first_known_browser, row_number() over (partition by to_date(started_at), customer_id order by started_at, id) as row_seq, row_number() over (order by started_at, id) as row_seq_2 from valid;
